package com.nova.config;
import com.nova.security.JwtService;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.Configuration;import org.springframework.messaging.Message;import org.springframework.messaging.MessageChannel;import org.springframework.messaging.simp.config.ChannelRegistration;import org.springframework.messaging.simp.config.MessageBrokerRegistry;import org.springframework.messaging.simp.stomp.StompCommand;import org.springframework.messaging.simp.stomp.StompHeaderAccessor;import org.springframework.messaging.support.ChannelInterceptor;import org.springframework.messaging.support.MessageHeaderAccessor;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.web.socket.config.annotation.*;import java.security.Principal;import java.util.List;
@Configuration @EnableWebSocketMessageBroker public class WebSocketConfig implements WebSocketMessageBrokerConfigurer {private final JwtService jwt;@Value("${app.cors.origins}") private String origins;public WebSocketConfig(JwtService jwt){this.jwt=jwt;}@Override public void registerStompEndpoints(StompEndpointRegistry registry){registry.addEndpoint("/ws-nova").setAllowedOriginPatterns(origins.split(","));}@Override public void configureMessageBroker(MessageBrokerRegistry config){config.enableSimpleBroker("/topic");config.setApplicationDestinationPrefixes("/app");}@Override public void configureClientInboundChannel(ChannelRegistration registration){registration.interceptors(new ChannelInterceptor(){@Override public Message<?> preSend(Message<?> message,MessageChannel channel){StompHeaderAccessor accessor=MessageHeaderAccessor.getAccessor(message,StompHeaderAccessor.class);if(accessor==null)return message;if(StompCommand.CONNECT.equals(accessor.getCommand())){String header=accessor.getFirstNativeHeader("Authorization");if(header==null||!header.startsWith("Bearer "))throw new AccessDeniedException("JWT required for WebSocket connection");try{var claims=jwt.claims(header.substring(7));if(!"ADMIN".equals(claims.get("role",String.class)))throw new AccessDeniedException("Admin role required");String email=claims.getSubject();Principal principal=new UsernamePasswordAuthenticationToken(email,null,List.of(new SimpleGrantedAuthority("ROLE_ADMIN")));accessor.setUser(principal);}catch(AccessDeniedException e){throw e;}catch(Exception e){throw new AccessDeniedException("Invalid WebSocket JWT");}}if(StompCommand.SUBSCRIBE.equals(accessor.getCommand())&&"/topic/jobs".equals(accessor.getDestination())&&(accessor.getUser()==null||accessor.getUser().getName()==null))throw new AccessDeniedException("Admin authentication required for job updates");return message;}});}}
